export const meta = {
  name: 'pr363-review-fixes-and-finish',
  description: 'Verify the PR #363 review fixes at 92e1d43 and fix what was left (scanner, lint, editor) in isolated worktrees',
  phases: [
    { title: 'Verify', detail: 'one verifier per fixed area' },
    { title: 'Fix', detail: 'one fixer per unfixed area, in its own worktree' },
  ],
}

const HEAD = '92e1d43fd03d0afa7526260bc861ba989cf1c1d1'
const OLD = 'f9e6739c87d1c0fe1655574295219ad914e97e96'
const BASE = 'c42e84a5b4eb85891d8562c3fdeb0c89ce6b38d9'
const JSON_PATH = '/tmp/claude-0/-home-user-burpsy/66b7b689-6882-5e3a-8187-823ee0e17adf/scratchpad/review363.json'

const CONTEXT = `Context: PR #363 (branch backlog-b9 -> master) in repo /home/user/burpsy, Go module burpsy-go/ plus React console burpsy-go/internal/web/ui. An earlier review at ${OLD} posted 39 findings. The original findings, with full text, are in ${JSON_PATH} (key "confirmed", a list; each has file, line, title, detail, scenario, verdict.comment). Two extra BFLA findings not in that file: (a) checks_bfla.go write replay decides "B was served" from 2xx + idorShapeOf(...).same(...), which compares JSON key paths and types only, so a 200 {"success":false,...} refusal is reported high/firm, and the detail text claims "that write was applied to the target" unverified; (b) checks_bfla.go doc says a write replay is "sent once" but NewProbeHarness re-sends the captured write as baseline, then B's replay, then the anonymous control (3 writes); scanner.go CheckBFLA/CheckAPIWrites docs still say "method escalation". Fixes were pushed; the head is now ${HEAD}. Fix commits are ${OLD}..${HEAD}.`

const COMMIT_RULES = `Working rules:
- You are in your own git worktree. First run \`git checkout --detach ${HEAD}\` (no other state to keep) and confirm \`git rev-parse HEAD\` = ${HEAD}.
- Fix exactly the listed defects, minimally, matching surrounding style and comment density. Each fix gets a regression test, and you must show the test FAILS without the fix (a negative control: revert the fix temporarily, run, restore).
- Never edit burpsy-go/internal/web/ui/dist/*, .beads/*, crates/*. Do not touch files outside your scope unless the fix needs it; say so if you do.
- Validate (from repo root): \`cd burpsy-go && gofmt -l <changed dirs>\` must be empty; \`go vet <changed pkgs>\`; tests via \`scripts/capped-run.sh -- sh -c 'cd burpsy-go && go test -count=1 -timeout 30m <pkgs>'\` (internal/scanner full is ~8 min; run it in full once at the end). UI: \`cd burpsy-go/internal/web/ui && bun run check\` and the relevant \`bun test <file>\`.
- Commit (one or more commits) with messages in the repo's style ("scanner: ..." etc.), each ending with exactly these two trailer lines after a blank line:
Co-Authored-By: Claude Opus 5.5 <noreply@anthropic.com>
Claude-Session: https://claude.ai/code/session_01BJixBxLeJF8fGS4y7ZTRLX
- Do not mention any model name elsewhere. Then run \`git branch -f BRANCH HEAD\` (BRANCH given below). Never push.
- Return: the branch, commit shas, per-finding outcome (fixed / not fixed + why), tests added, the negative-control evidence, and the exact validation commands you ran with pass/fail.`

const FIX_SCHEMA = {
  type: 'object',
  properties: {
    branch: { type: 'string' },
    commits: { type: 'array', items: { type: 'string' } },
    outcomes: { type: 'array', items: { type: 'object', properties: { finding: { type: 'string' }, status: { type: 'string', enum: ['fixed', 'not_fixed'] }, note: { type: 'string' } }, required: ['finding', 'status', 'note'] } },
    validation: { type: 'string' },
    files: { type: 'array', items: { type: 'string' } },
  },
  required: ['branch', 'commits', 'outcomes', 'validation', 'files'],
}

const VERIFY_SCHEMA = {
  type: 'object',
  properties: {
    items: { type: 'array', items: { type: 'object', properties: {
      finding: { type: 'string', description: 'file:line + short title of the original finding' },
      status: { type: 'string', enum: ['fixed', 'partially_fixed', 'not_fixed', 'fixed_but_regressed'] },
      evidence: { type: 'string', description: 'how you checked: code read, test run, repro' },
      remaining: { type: 'string', description: 'what is still wrong, concretely, or empty' },
    }, required: ['finding', 'status', 'evidence', 'remaining'] } },
    new_defects: { type: 'array', items: { type: 'object', properties: { file: { type: 'string' }, line: { type: 'integer' }, severity: { type: 'string', enum: ['major', 'minor'] }, description: { type: 'string' } }, required: ['file', 'line', 'severity', 'description'] } },
  },
  required: ['items', 'new_defects'],
}

const VERIFY_AREAS = [
  { key: 'ui-gate', scope: 'the gated-route resolver: burpsy-go/internal/web/ui/src/lib/api.ts manifestPatternFor/gatedPatternFor, gated-routes.ts/.test.ts, and the Sequencer stop/pause/resume path (data.workbench.ts, sequencer.tsx). Compare the client resolver with the Go side (confirm_gate.go routeRiskFor/patternMatches/literalLen) over every key in the generated table, not just sequencer: any path where client and server disagree is a defect.' },
  { key: 'ui-editor', scope: 'UI editor/settings/protobuf/tabs fixes: lib/editor-eol.ts (+test), ui/editor.tsx, lib/message.ts (mixed-ending), pages/settings.tsx Revert, ui/protobuf-view.tsx staleness guard, app.tsx + lib/tool-tabs.ts tab-order chords, pages/repeater.tsx plugin hotkey. Note: mixed-ending DISPLAY fidelity (finding editor.tsx:1203) is acknowledged as still open; judge only whether what was changed is correct and whether it regressed anything.' },
  { key: 'sender', scope: 'burpsy-go/internal/sender: read.go deadline/cancel salvage, sender.go close-delimited Connection rewrite, h3.go pin (egress policy refusal, TLS verify, body cap), protocol.go, h2sessions.go deprecation change.' },
  { key: 'proxy', scope: 'burpsy-go/internal/proxy/proxy.go h3 Alt-Svc leg (no replay of uncertain deliveries, dial vs exchange timeouts, egress policy/carrier/resolution override, forForwarding, learnFromChallenge/altSvc.learn), the hook-dropped response vs intercept hold (both sites incl. completeResponse), and burpsy-go/internal/httputil/h3.go body cap + httputil.go change.' },
  { key: 'crawler', scope: 'burpsy-go/internal/crawler: credential_login.go self-registration cap/dedup and repeated-login-form record, apidoc.go SDL sniff vs JavaScript, crawler.go change; also the race-web-0 test TestTheCrawlRouteClicksThroughToAScriptRoutedPage that timed out earlier (passes now on CI; check whether anything here was a real cause).' },
  { key: 'agent-mcp', scope: 'burpsy-go/internal/agent run.go MaxSteps within a turn and subtask.go; burpsy-go/internal/mcp tools.go legacyOp for {id}/{param} routes and the intruder_control {id} op, and groups.go (MCP risk-class placement is a security boundary: check no op moved to a less-gated group).' },
  { key: 'misc', scope: 'burpsy-go/internal/intruder limit.go PaceN atomic + cancellable, payload.go plugin source decode, web intruder plugin tests asserting the real refusal; burpsy-go/internal/grpcproto reflection.go deterministic entry + schema.go; web/api_repeater_graphql.go offset fix; web/extension_services.go conversions; scripts/capped-run.sh lock fd; .github/workflows/nightly.yml probe + pinned image and scripts/bench files.' },
]

const FIXES = [
  { key: 'idor', branch: 'pr363fix/idor', scope: 'burpsy-go/internal/scanner/checks_idor.go findings at lines ~202 (idorReidentity covered=true without substituting B) and ~224 (two-identity cross-read firm with no ownership evidence). Read both full findings in the JSON.' },
  { key: 'oauth', branch: 'pr363fix/oauth', scope: 'burpsy-go/internal/scanner/checks_oauth.go findings at ~182 (redirect_uri not QueryEscape-encoded => silent no-op), ~193 (canary host anywhere in Location / raw response), ~219 (state-missing fires on any 302 incl. error redirects). Also the lint finding checks_oauth.go:32 gosec G101 on the issue-name constant (a false positive: add a justified //nolint:gosec // G101: ... comment in the repo style, check scripts/ci/golangci.yml for how other suppressions are written).' },
  { key: 'smuggling', branch: 'pr363fix/cl0', scope: 'burpsy-go/internal/scanner/checks_smuggling.go ~346: the CL.0 smuggled-prefix probe re-enabled inside the main smuggling check and in checkClientSideDesync. Keep it out of the default run: gate it behind an explicit opt-in (look at how other unsafe probes are opted into in scanner.go ScanConfig and how the deleted runner declined it in git history: `git log -S CL0 --oneline` / `git log -p` on the file). Fix the finding text that claims nothing was queued for any other user. If you add a ScanConfig switch, wire it like its neighbours (config keys, web scannerConfigBoolKeys / UI switch list if that is how switches are surfaced, docs) and keep it off by default.' },
