	// ConsecutiveCheckFailuresToAbandonUnit is Burp's
	// `consecutive_audit_check_failures_to_skip_insertion_point`.
	ConsecutiveCheckFailuresToAbandonUnit uint32
	// ConsecutiveUnitFailuresToFailItem is Burp's
	// `consecutive_insertion_point_failures_to_fail_audit_item`.
	ConsecutiveUnitFailuresToFailItem uint32
	// MaxUnitVariantsPerUnit caps how many distinct content variants of one (scope, endpoint)
	// dispatch unit a run will dispatch (burpsy-go W4). The shape fingerprint masks the
	// well-known volatile regions; this caps what masking cannot know about - a volatile
	// region with an unrecognized name re-mints a unit per capture, and without a bound the
	// re-dispatch is limited only by capture count. Variants beyond the cap are counted
	// AlreadyCovered (the scope's checks DID cover this endpoint this run) and the unit is
	// reported in AuditOutcome.UnitsVariantCapped. 0 = unlimited, the pre-W4 behaviour.
	MaxUnitVariantsPerUnit uint32
	// PauseSessionAfterFailedItems is Burp's `pause_task_failed_audit_item_count`.
	PauseSessionAfterFailedItems uint32
// unitVariantCapped reports whether this dispatch unit is a content variant beyond the run's
// cap (burpsy-go W4), admitting the variant's key on first sight so a re-walk of the same unit
// (a follow-up pass, or a re-capture of identical content) is never capped after the fact.
//
// Passive units are exempt: their key carries the "|passive" suffix, and re-running them on new
// content costs analysis of an exchange already in hand, not requests. Units without a content
// fingerprint (per-request, per-insertion-point) are exempt by construction - they key by
// exchange ID, so every capture is meant to be its own unit.
func (r *auditRun) unitVariantCapped(key string) bool {
	if strings.HasSuffix(key, "|passive") {
		return false
	}
	capN := r.cfg.MaxUnitVariantsPerUnit
	if capN == 0 {
		return false
	}
	i := strings.Index(key, "#fp")
	if i < 0 {
		return false
	}
	base := key[:i]
	r.mu.Lock()
	defer r.mu.Unlock()
	if r.unitVariants == nil {
		r.unitVariants = make(map[string]map[string]bool)
	}
	set := r.unitVariants[base]
	if set == nil {
		set = make(map[string]bool)
		r.unitVariants[base] = set
	}
	if set[key] {
		return false
	}
	if uint64(len(set)) >= uint64(capN) {
		return true
	}
	set[key] = true
	return false
}

// outOfTime reports whether the wall-clock budget is spent.
func (r *auditRun) outOfTime() bool {
	return !r.deadline.IsZero() && !time.Now().Before(r.deadline)
}

