// volatile: they carry the answer's verdict ({"updated":false} versus true).
func bflaVolatileLeaf(path, value string) bool {
	if value == "true" || value == "false" || value == "null" {
		return false
	}
	last := path[strings.LastIndexAny(path, ".]")+1:]
