func (sm *SiteMap) observedLocked(host string, port uint16, tls bool, path string) bool {
	if path == "" {
		return sm.hosts[hostKey(host, port, tls)] != nil
	}
	return sm.nodes[insertKey(host, port, tls, NodePath(path))] > 0
}

