// that lands after the operator moved on - typed over the draft, edited the Raw view, or left
// the message - writes nothing and says why (the rsu2 generation guard).
import { afterEach, beforeEach, describe, expect, test } from "bun:test";
import { cleanup, fireEvent, screen, waitFor } from "@testing-library/react";
import { renderWithProviders } from "../../test/render";
import type { GraphQLDocument } from "../lib/message-views";
import { GraphQLView } from "./typed-views";

const RAW =
 'POST /graphql HTTP/1.1\r\nHost: shop.example\r\nContent-Type: application/json\r\nContent-Length: 14\r\n\r\n{"query":"{a}"}';
const DOC: GraphQLDocument = {
 source: "JSON body",
 operations: [{ operationName: null, query: "{a}", variables: null, extensions: null }],
};

const originalFetch = globalThis.fetch;
let resolveApply: ((response: Response) => void) | null = null;
let resolveCheck: ((response: Response) => void) | null = null;

beforeEach(() => {
 resolveApply = null;
 resolveCheck = null;
 globalThis.fetch = (async (input: RequestInfo | URL) => {
  const path = new URL(String(input), "http://localhost").pathname;
  if (path === "/api/repeater/graphql-query") {
   return await new Promise<Response>((resolve) => {
    resolveApply = resolve;
   });
  }
  if (path === "/api/repeater/graphql-validate") {
   return await new Promise<Response>((resolve) => {
    resolveCheck = resolve;
   });
  }
  return new Response("{}", { status: 200, headers: { "content-type": "application/json" } });
 }) as typeof fetch;
});
afterEach(() => {
 cleanup();
 globalThis.fetch = originalFetch;
});

function appliedResponse(request: string): Response {
 return new Response(JSON.stringify({ request, source: "body" }), {
  status: 200,
  headers: { "content-type": "application/json" },
 });
}

async function startPendingApply(onChange: (next: string) => void) {
 const view = renderWithProviders(<GraphQLView document={DOC} raw={RAW} onChange={onChange} />);
 fireEvent.change(screen.getByLabelText("Edit this operation's GraphQL query"), { target: { value: "{b}" } });
 fireEvent.click(screen.getByRole("button", { name: "Apply to request" }));
 await waitFor(() => expect(resolveApply).not.toBeNull());
 return view;
}

describe("a pending Apply never overwrites a newer edit", () => {
 test("a raw prop move under the pending Apply voids the resolution", async () => {
  const applied: string[] = [];
  const { rerender } = await startPendingApply((next) => applied.push(next));
  rerender(<GraphQLView document={DOC} raw={RAW + "\r\n"} onChange={(next) => applied.push(next)} />);
  resolveApply?.(appliedResponse("POST /graphql HTTP/1.1\r\n\r\n{\"query\":\"{b}\"}"));
  await waitFor(() => expect(screen.getByText(/draft changed while Apply was running/)).toBeTruthy());
  expect(applied).toEqual([]);
 });

 test("an unmount with the Apply in flight voids the resolution", async () => {
  const applied: string[] = [];
  const { unmount } = await startPendingApply((next) => applied.push(next));
  unmount();
  resolveApply?.(appliedResponse("POST /graphql HTTP/1.1\r\n\r\n{\"query\":\"{b}\"}"));
  await new Promise((resolve) => setTimeout(resolve, 20));
  expect(applied).toEqual([]);
 });

 test("a resolution that lands before anything moved still applies", async () => {
  const applied: string[] = [];
  await startPendingApply((next) => applied.push(next));
  resolveApply?.(appliedResponse("POST /graphql HTTP/1.1\r\n\r\n{\"query\":\"{b}\"}"));
  await waitFor(() => expect(applied).toEqual(['POST /graphql HTTP/1.1\r\n\r\n{"query":"{b}"}']));
 });
});

describe("a pending Check never lands on a newer draft", () => {
 test("a raw prop move under the pending Check voids the resolution", async () => {
  const { rerender } = renderWithProviders(<GraphQLView document={DOC} raw={RAW} onChange={() => undefined} />);
  fireEvent.change(screen.getByLabelText("Edit this operation's GraphQL query"), { target: { value: "{b}" } });
  fireEvent.click(screen.getByRole("button", { name: "Check" }));
  await waitFor(() => expect(resolveCheck).not.toBeNull());
  rerender(<GraphQLView document={DOC} raw={RAW + "\r\n"} onChange={() => undefined} />);
  resolveCheck?.(new Response(JSON.stringify({ ok: true, errors: [] }), {
   status: 200,
   headers: { "content-type": "application/json" },
  }));
  await new Promise((resolve) => setTimeout(resolve, 20));
  expect(screen.queryByText("The document parses.")).toBeNull();
 });

 test("a Check that lands before anything moved still reports", async () => {
  renderWithProviders(<GraphQLView document={DOC} raw={RAW} onChange={() => undefined} />);
  fireEvent.change(screen.getByLabelText("Edit this operation's GraphQL query"), { target: { value: "{b}" } });
  fireEvent.click(screen.getByRole("button", { name: "Check" }));
  await waitFor(() => expect(resolveCheck).not.toBeNull());
  resolveCheck?.(new Response(JSON.stringify({ ok: true, errors: [] }), {
   status: 200,
   headers: { "content-type": "application/json" },
  }));
  await waitFor(() => expect(screen.getByText("The document parses.")).toBeTruthy());
 });
});

// The .proto file SET on the Protobuf tab (burpsy-react-ui-rsu2): picking several files loads them
// as one schema whose imports resolve across the set, the entry point is re-pickable, and the
// decode call sends proto_entry + proto_files rather than the single-file proto field.
import { afterEach, beforeEach, describe, expect, test } from "bun:test";
import { cleanup, fireEvent, screen, waitFor } from "@testing-library/react";
import { renderWithProviders } from "../../test/render";
import { useApp } from "../lib/store";
import { ProtobufView } from "./protobuf-view";

const originalFetch = globalThis.fetch;
let decodeCalls: Record<string, unknown>[] = [];
const json = (b: unknown, status = 200) => new Response(JSON.stringify(b), { status, headers: { "content-type": "application/json" } });
const SCHEMALESS = { grpc: false, frames: [{ fields: [{ number: 1, wire_type: 2, len_kind: "string", string: "x" }] }] };

beforeEach(() => {
 decodeCalls = [];
 useApp.setState({ protoSchema: null, protoMessages: {} } as never);
 globalThis.fetch = (async (input: RequestInfo | URL, init?: RequestInit) => {
  const path = new URL(String(input), "http://localhost").pathname;
  if (path === "/api/protobuf/decode") {
   decodeCalls.push(JSON.parse(String(init?.body ?? "{}")) as Record<string, unknown>);
   return json(SCHEMALESS);
  }
  return json({}, 404);
 }) as typeof fetch;
});
afterEach(() => {
 cleanup();
 globalThis.fetch = originalFetch;
});

async function pickFiles(files: File[]) {
 const input = (await waitFor(() => {
  const el = document.querySelector('input[type="file"]');
  if (!el) throw new Error("no file input yet");
  return el;
 })) as HTMLInputElement;
 fireEvent.change(input, { target: { files } });
}

describe("the .proto file set on the Protobuf tab", () => {
 test("several picked files load as one set and the decode sends proto_entry + proto_files", async () => {
  renderWithProviders(<ProtobufView bodyBase64="CgN4" grpc={false} direction="request" />);
  await pickFiles([
   new File(['syntax = "proto3"; package shop; import "protos/common.proto"; message GetReq { common.Id id = 1; }'], "protos/shop.proto"),
   new File(['syntax = "proto3"; package common; message Id { string value = 1; }'], "protos/common.proto"),
  ]);
  await waitFor(() => expect(useApp.getState().protoSchema?.files).toBeTruthy());
  expect(useApp.getState().protoSchema?.entry).toBe("protos/shop.proto");
  await waitFor(() => expect(decodeCalls.length).toBeGreaterThan(0));
  const last = decodeCalls[decodeCalls.length - 1] ?? {};
  expect(last.proto).toBeUndefined();
  expect(last.proto_entry).toBe("protos/shop.proto");
  expect(Object.keys(last.proto_files as Record<string, string>).sort()).toEqual(["protos/common.proto", "protos/shop.proto"]);
 });

 test("one picked file stays the single-file form", async () => {
  renderWithProviders(<ProtobufView bodyBase64="CgN4" grpc={false} direction="request" />);
  await pickFiles([new File(['syntax = "proto3"; message A { int32 a = 1; }'], "a.proto")]);
  await waitFor(() => expect(useApp.getState().protoSchema?.text).toContain("message A"));
  expect(useApp.getState().protoSchema?.files).toBeUndefined();
  await waitFor(() => expect(decodeCalls.length).toBeGreaterThan(0));
  const last = decodeCalls[decodeCalls.length - 1] ?? {};
  expect(last.proto).toContain("message A");
  expect(last.proto_files).toBeUndefined();
 });

 test("same-named files with different content are dropped loudly, never silently collapsed", async () => {
  renderWithProviders(<ProtobufView bodyBase64="CgN4" grpc={false} direction="request" />);
  await pickFiles([
   new File(['syntax = "proto3"; message One { int32 a = 1; }'], "dup.proto"),
   new File(['syntax = "proto3"; message Two { int32 b = 2; }'], "dup.proto"),
   new File(['syntax = "proto3"; message Three { int32 c = 3; }'], "solo.proto"),
  ]);
  await waitFor(() => expect(useApp.getState().protoSchema?.files).toBeTruthy());
  const schema = useApp.getState().protoSchema;
  expect(Object.keys(schema?.files ?? {}).sort()).toEqual(["dup.proto", "solo.proto"]);
  expect(schema?.files?.["dup.proto"]).toContain("message One");
  expect(schema?.name).toBe("2 .proto files");
 });

 test("re-picking the entry clears the message types chosen against the old one", async () => {
  useApp.setState({
   protoSchema: {
    name: "2 .proto files",
    text: "b",
    files: { "a.proto": "a", "b.proto": "b" },
    entry: "a.proto",
   },
   protoMessages: { request: "shop.GetReq" },
  } as never);
  renderWithProviders(<ProtobufView bodyBase64="CgN4" grpc={false} direction="request" />);
  const entrySelect = await screen.findByLabelText("Entry point of the .proto file set");
  fireEvent.change(entrySelect, { target: { value: "b.proto" } });
  await waitFor(() => expect(useApp.getState().protoSchema?.entry).toBe("b.proto"));
  expect(useApp.getState().protoMessages).toEqual({});
 });

 test("a pick batch a newer pick superseded never lands", async () => {
  renderWithProviders(<ProtobufView bodyBase64="CgN4" grpc={false} direction="request" />);
  const slow = new File(['syntax = "proto3"; message Slow { int32 a = 1; }'], "slow.proto");
  slow.text = () => new Promise<string>((resolve) => setTimeout(() => resolve('syntax = "proto3"; message Slow { int32 a = 1; }'), 50));
  await pickFiles([slow]);
  await pickFiles([new File(['syntax = "proto3"; message Fast { int32 a = 1; }'], "fast.proto")]);
  await waitFor(() => expect(useApp.getState().protoSchema?.name).toBe("fast.proto"));
  await new Promise((resolve) => setTimeout(resolve, 100));
  expect(useApp.getState().protoSchema?.name).toBe("fast.proto");
 });

 test("the entry point is re-pickable and the next decode uses it", async () => {
  useApp.setState({
   protoSchema: {
    name: "2 .proto files",
    text: "b",
    files: { "a.proto": "a", "b.proto": "b" },
    entry: "a.proto",
   },
  } as never);
  renderWithProviders(<ProtobufView bodyBase64="CgN4" grpc={false} direction="request" />);
  const entrySelect = await screen.findByLabelText("Entry point of the .proto file set");
  fireEvent.change(entrySelect, { target: { value: "b.proto" } });
  await waitFor(() => expect(useApp.getState().protoSchema?.entry).toBe("b.proto"));
  await waitFor(() => expect(decodeCalls.some((c) => c.proto_entry === "b.proto")).toBe(true));
 });
});

// A file-set pick resolves asynchronously. A clear or a paste made while it is pending is the newer
// decision: the pick must not land on top of it (burpsy-react-ui-pggap).
describe("a pending .proto pick never overwrites a later clear or paste", () => {
 const pendingFiles = () => {
  let release: () => void = () => {};
  const gate = new Promise<void>((resolve) => {
   release = resolve;
  });
  const file = (name: string, text: string) => ({ name, text: () => gate.then(() => text) }) as unknown as File;
  return { files: [file("a.proto", 'syntax = "proto3"; message A {}'), file("b.proto", 'syntax = "proto3"; message B {}')], release };
 };

 test("Clear schema wins over a pick that resolves after it", async () => {
  useApp.setState({ protoSchema: { name: "old.proto", text: 'syntax = "proto3"; message Old {}' } } as never);
  renderWithProviders(<ProtobufView bodyBase64="CgN4" grpc={false} direction="request" />);
  const { files, release } = pendingFiles();
  await pickFiles(files);
  fireEvent.click(await screen.findByRole("button", { name: "Clear schema" }));
  release();
  await new Promise((r) => setTimeout(r, 20));
  expect(useApp.getState().protoSchema).toBeNull();
 });

 test("a pasted schema wins over a pick that resolves after it", async () => {
  renderWithProviders(<ProtobufView bodyBase64="CgN4" grpc={false} direction="request" />);
  const { files, release } = pendingFiles();
  await pickFiles(files);
  fireEvent.click(await screen.findByRole("button", { name: "Paste .proto" }));
  fireEvent.change(screen.getByLabelText(".proto source"), { target: { value: 'syntax = "proto3"; message Pasted {}' } });
  fireEvent.click(screen.getByRole("button", { name: "Use this schema" }));
  release();
  await new Promise((r) => setTimeout(r, 20));
  expect(useApp.getState().protoSchema?.name).toBe("pasted .proto");
 });
});

