func countAfterDropDecision(t *testing.T, store *core.TrafficStore, options *Options, want uint64) int {
	t.Helper()
	deadline := time.Now().Add(5 * time.Second)
	for options.Counters().DroppedOutOfScope < want {
		if time.Now().After(deadline) {
