					Request:  []byte("GET / HTTP/1.1\r\nHost: " + host + "\r\n\r\n"),
					Response: []byte("HTTP/1.1 200 OK\r\nContent-Length: " + fmt.Sprint(len(host)) + "\r\n\r\n" + host),
				}); err != nil {
					t.Errorf("record: %v", err)
					return
				}
				captured.Add(1)
			}
		}(w)
	}
	done := make(chan struct{})
	go func() {
		defer close(done)
		for i := 1; i <= switches; i++ {
			for start := captured.Load(); captured.Load() < start+40; {
				runtime.Gosched()
			}
			if rec := openProjectSwitch(t, srv, filepath.Join(dir, fmt.Sprintf("p%d.db", i))); rec.Code != http.StatusOK {
