		}
	}()
	select {
	case <-done:
	case <-time.After(60 * time.Second):
		t.Fatal("project switches did not complete within 60s")
	}
	close(stop)
	wg.Wait()

	split := 0
	for i := 0; i < switches; i++ {
		path := filepath.Join(dir, fmt.Sprintf("p%d.db", i))
		p, err := persist.Open(path, zap.NewNop())
		if err != nil {
			t.Fatal(err)
		}
		msgs, err := p.LoadMessages(nil)
		if err != nil {
			t.Fatal(err)
		}
		raw := make(map[uint64][]byte, len(msgs))
		for _, m := range msgs {
			raw[uint64(m.ID)] = m.Raw()
		}
		exs, err := p.LoadExchanges()
		if err != nil {
			t.Fatal(err)
		}
		for _, ex := range exs {
			for _, id := range []*uint64{msgID(ex.Request), msgID(ex.Response)} {
				if id == nil {
					continue
				}
				if b, ok := raw[*id]; !ok || !bytes.Contains(b, []byte(ex.Host)) {
					split++
