						t.Errorf("%s: exchange %d (%s) names message %d, which this project holds as %q",
							filepath.Base(path), ex.ID, ex.Host, *id, b)
					}
				}
			}
		}
		_ = p.Close()
	}
	if split > 0 {
		t.Errorf("%d exchange→message references crossed a project boundary", split)
	}
