package web

import (
	"bytes"
	"context"
	"encoding/json"
	"fmt"
	"net"
	"net/http"
	"net/http/httptest"
	"reflect"
	"sort"
	"strconv"
	"strings"
	"sync/atomic"
	"testing"
	"time"

	"github.com/burpsy-go/burpsy/internal/core"
	"github.com/burpsy-go/burpsy/internal/scanner"
	"github.com/burpsy-go/burpsy/internal/sender"
	"go.uber.org/zap"
)

// TestEveryEgressAndAttackRouteRefusesAnOutOfScopeTarget drives every riskEgress and riskAttack
// route-verb in the manifest at a loopback listener the scope EXCLUDES, and requires that the
// listener accepts no connection at all (burpsy-react-ui-egress-matrix). Per-engine scope tests use
// in-scope targets; a new egress route that built its own transport would pass them and still send
// to an out-of-scope host. This catches that by construction: bodies come from each handler's own
// request type (routeSchemas), every target-shaped field names the excluded listener, and an
// exchange to it is seeded for the routes that re-send a captured one.
//
// The assertion is zero accepted connections, whatever each route answers: a 400 for a body the
// generator could not satisfy proves nothing either way, so the count of routes that answered 2xx is
// logged to show how much of the surface was actually exercised.
func TestEveryEgressAndAttackRouteRefusesAnOutOfScopeTarget(t *testing.T) {
	ln, err := net.Listen("tcp", "127.0.0.1:0")
	if err != nil {
		t.Fatal(err)
	}
	defer ln.Close()
	var accepted atomic.Int64
	go func() {
		for {
			c, err := ln.Accept()
			if err != nil {
				return
			}
			accepted.Add(1)
			_ = c.Close()
		}
	}()
	port := ln.Addr().(*net.TCPAddr).Port
	target := fmt.Sprintf("http://127.0.0.1:%d/x?q=1", port)
	rawReq := fmt.Sprintf("GET /x?q=1 HTTP/1.1\r\nHost: 127.0.0.1:%d\r\n\r\n", port)

	scope := core.NewScope()
	scope.AddInclude("allowed.test") // the listener (127.0.0.1) is out of scope
	store := core.NewTrafficStore()
	reqID, _ := store.Put([]byte(rawReq), core.DirectionRequest)
	respID, _ := store.Put([]byte("HTTP/1.1 200 OK\r\nContent-Length: 2\r\n\r\nok"), core.DirectionResponse)
	store.AddExchange(&core.Exchange{Host: "127.0.0.1", Port: uint16(port), Method: "GET", Path: "/x?q=1",
		Request: core.MsgPtr(reqID), Response: &respID})
	cfg := sender.DefaultSenderConfig()
	cfg.Timeout = 2 * time.Second
	snd := sender.NewSender(cfg)
	s := NewServer(store, scope).WithSender(snd).WithScanner(scanner.NewActiveScanner(store, zap.NewNop()))

	fill := bodyFiller{target: target, raw: rawReq, port: port}
	var exercised, total int
	var hung []string
	patterns := make([]string, 0, len(manifest))
	for p := range manifest {
		patterns = append(patterns, p)
	}
	sort.Strings(patterns)
	for _, pattern := range patterns {
		r := manifest[pattern]
		if r.risk != riskEgress && r.risk != riskAttack {
			continue
		}
		for _, method := range r.methods {
			if method == http.MethodGet || method == http.MethodHead || method == http.MethodOptions {
				continue
			}
			path := concretePath(pattern, r.subPath)
			var body []byte
			if sch, ok := routeSchemas[method+" "+pattern]; ok && sch.body != nil {
				body, _ = json.Marshal(fill.value(sch.body, "", 0))
			} else {
				body = []byte("{}")
			}
			total++
			ctx, cancel := context.WithTimeout(context.Background(), 3*time.Second)
			req := httptest.NewRequest(method, path, bytes.NewReader(body)).WithContext(ctx)
			req.Header.Set("Content-Type", "application/json")
			rec := httptest.NewRecorder()
			done := make(chan struct{})
			go func() { s.mux.ServeHTTP(rec, req); close(done) }()
			select {
			case <-done:
				if rec.Code >= 200 && rec.Code < 300 {
					exercised++
				}
			case <-time.After(5 * time.Second):
				hung = append(hung, method+" "+path)
			}
			cancel()
		}
	}
	time.Sleep(1500 * time.Millisecond) // background tasks a route started get their chance to send
	t.Logf("%d egress/attack route-verbs driven, %d answered 2xx, %d still running after 5s", total, exercised, len(hung))
	if total < 20 {
		t.Fatalf("only %d egress/attack route-verbs found in the manifest; the matrix is not seeing the surface", total)
