// hostRoutingFinding reports an internal name in Host selecting a different application (0vzb.42).
// Two random .invalid hosts show what the server answers for an unknown name (its default vhost);
// an internal name that answers 2xx, unlike both the baseline and that default, twice, is routed
// somewhere else.
func hostRoutingFinding(cc *CheckContext, base []byte, authority string, send func([]byte) (ProbeResponse, bool)) []*Finding {
	d1, ok1 := send(withHostHeaders(base, hostCanary()))
	d2, ok2 := send(withHostHeaders(base, hostCanary()))
	if !ok1 || !ok2 {
		return nil
	}
	dflt := newBooleanComparator(d1.Status, d1.Body, d2.Status, d2.Body)
	if !dflt.stable() {
		return nil
	}
	b := cc.Exchange
	baseRes := ProbeResponse{}
	if r, ok := send(base); ok {
		baseRes = r
	}
	orig := newBooleanComparator(baseRes.Status, baseRes.Body, baseRes.Status, baseRes.Body)
	port := ""
	if i := strings.LastIndexByte(authority, ':'); i > 0 && !strings.HasSuffix(authority, "]") {
		port = authority[i:]
	}
	for _, name := range []string{"localhost", "127.0.0.1", "admin", "internal", "intranet"} {
		r1, ok := send(withHostHeaders(base, name+port))
		if !ok || r1.Status < 200 || r1.Status >= 300 {
			continue
		}
		if dflt.sameAsBase(dflt.page(r1.Status, r1.Body, "")) || orig.sameAsBase(orig.page(r1.Status, r1.Body, "")) {
			continue
		}
		r2, ok := send(withHostHeaders(base, name+port))
		if !ok || r2.Status != r1.Status || !dflt.alike(dflt.page(r1.Status, r1.Body, ""), dflt.page(r2.Status, r2.Body, "")) {
			continue
		}
		f := buildProbeFinding(cc, IssueHostHeaderInjection, "firm",
			fmt.Sprintf("Host: %s -> HTTP %d, %d bytes (unknown host -> HTTP %d)", name+port, r1.Status, len(r1.Body), d1.Status),
			fmt.Sprintf("with Host: %s the server at %s answered %d with a page unlike both the original "+
				"response and what it serves for an unknown host name, twice. The Host header selects another "+
				"application (virtual host); an attacker can reach an internal site through this front end.",
				name+port, b.Host, r1.Status))
		f.Severity = "low"
		return []*Finding{f}
	}
	return nil
}

