}

func (s *stickyHost) ServeHTTP(w http.ResponseWriter, r *http.Request) {
	s.mu.Lock()
	if s.host == "" && !strings.HasPrefix(r.Host, "127.0.0.1") {
		s.host = r.Host
	}
	h := s.host
	s.mu.Unlock()
	if h == "" {
		h = "app.example.test"
	}
	w.Header().Set("Content-Type", "text/html")
	fmt.Fprintf(w, `<a href="https://%s/home">home</a>`, h)
