	for i, c := range cases {
		if got := len(hostURLSightings(base, c.raw, "evil.invalid", false)) > 0; got != c.want {
			t.Errorf("case %d (%q): sighted = %v, want %v", i, c.raw, got, c.want)
		}
	}
}

