package domexec

import (
	"context"
	"fmt"
	"io"
	"net/http"
	"testing"
	"time"

	"github.com/burpsy-go/burpsy/internal/domexec/domexectest"
)

func TestTheDefaultGateCoversUngatedNavigations(t *testing.T) {
	b, err := NewBrowser(context.Background(), Options{Timeout: 30 * time.Second})
	if err != nil {
		domexectest.Skipf(t, "no browser could be launched: %v", err)
	}
	t.Cleanup(func() { _ = b.Close() })
	outside, outsideAccepts := countingServer(t, http.HandlerFunc(func(http.ResponseWriter, *http.Request) {}))
	inside, _ := countingServer(t, http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		w.Header().Set("Content-Type", "text/html")
		_, _ = fmt.Fprintf(w, `<script src="%s/x.js"></script><img src="%[1]s/p.gif">`, outside.URL)
	}))
	b.SetDefaultGate(gateFor(t, inside.URL))
	ctx, cancel := context.WithTimeout(context.Background(), 30*time.Second)
	defer cancel()
	html, _, err := b.RenderedDOMWithOptions(ctx, inside.URL+"/", RenderOptions{MaxWait: 2 * time.Second})
	if err != nil || html == "" {
		t.Fatalf("in-scope page did not render: %v", err)
	}
	if _, err := b.ObserveTaint(ctx, outside.URL+"/", nil); err == nil {
		_ = io.EOF
	}
	if n := outsideAccepts.Load(); n != 0 {
		t.Fatalf("out-of-scope host got %d connection(s)", n)
	}
}
EOF
